50	    /**
51	     * Formats an owner's self-link, as required by the API's read-only {@code selfLink}
52	     * field: the canonical API path {@code '/api/owners/'} followed by the owner's id.
53	     * Returns {@code null} when the owner has no id yet.
54	     *
55	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
56	     * applied only where referenced via {@code qualifiedByName}.
57	     */
58	    @Named("formatSelfLink")
59	    default String formatSelfLink(Owner owner) {
60	        if (owner == null || owner.getId() == null) {
61	            return null;
62	        }
63	        return "/api/owners/" + owner.getId();
64	    }
65	
66	    /**
67	     * Formats an owner's salutation, as required by the API's read-only {@code salutation}
68	     * field: the owner's title and last name separated by a single space (e.g. {@code 'DR Who'})
69	     * when a title is present, or just the last name when no title was supplied.
70	     *
71	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
72	     * applied only where referenced via {@code qualifiedByName}.
73	     */
74	    @Named("formatSalutation")
75	    default String formatSalutation(Owner owner) {
76	        if (owner == null) {
77	            return null;
78	        }
79	        String title = owner.getTitle();
80	        if (title == null || title.isEmpty()) {
81	            return owner.getLastName();
82	        }
83	        return title + " " + owner.getLastName();
84	    }
