86	    /**
87	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
88	     * last names, as required by the API's read-only {@code displayName} field.
89	     *
90	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
91	     * applied only where referenced via {@code qualifiedByName}.
92	     */
93	    @Named("formatDisplayName")
94	    default String formatDisplayName(Owner owner) {
95	        if (owner == null) {
96	            return null;
97	        }
98	        return owner.getLastName() + ", " + owner.getFirstName();
99	    }
