101	    /**
102	     * Formats an owner's initials as the upper-cased first letters of the first and last
103	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
104	     * API's read-only {@code initials} field.
105	     *
106	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
107	     * applied only where referenced via {@code qualifiedByName}.
108	     */
109	    @Named("formatInitials")
110	    default String formatInitials(Owner owner) {
111	        if (owner == null) {
112	            return null;
113	        }
114	        return initial(owner.getFirstName()) + initial(owner.getLastName());
115	    }
