117	    /**
118	     * Formats an owner's stored E.164 telephone for human display, as required by the API's
119	     * read-only {@code telephoneDisplay} field: the country code (with its leading {@code '+'}),
120	     * a space, then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The
121	     * raw {@code telephone} field keeps its canonical E.164 form. Returns {@code null} when no
122	     * telephone is present.
123	     *
124	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
125	     * applied only where referenced via {@code qualifiedByName}.
126	     */
127	    @Named("formatTelephoneDisplay")
128	    default String formatTelephoneDisplay(Owner owner) {
129	        if (owner == null) {
130	            return null;
131	        }
132	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
133	    }
134	
135	    /**
136	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
137	     * {@code customerCode} is the owner's {@code '<REGION>-<HASH8>'} customer code and
138	     * {@code YY} is the last two digits of the fiscal year (the fiscal year starting on
139	     * 1 July) of the business-day-adjusted registration date (e.g. {@code 'NSW-1A2B3C4D-M26'}),
140	     * as required by the API's read-only {@code membershipNumber} field. Returns {@code null}
141	     * when either the customer code or registration date is absent.
142	     *
143	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
144	     * applied only where referenced via {@code qualifiedByName}.
145	     */
146	    @Named("formatMembershipNumber")
147	    default String formatMembershipNumber(Owner owner) {
148	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
149	            return null;
150	        }
151	        return String.format("%s-M%02d", owner.getCustomerCode(),
152	            fiscalYearStart(owner.getRegistrationDate()) % 100);
153	    }
154	
155	    /**
156	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, as required by the API's read-only
157	     * {@code fiscalYear} field: the fiscal year of the business-day-adjusted registration date,
158	     * where the fiscal year starts on 1 July and {@code YY} is the last two digits of the
159	     * calendar year in which that fiscal year begins (so a registration date of
160	     * {@code 2026-10-02} yields {@code 'FY26'} and {@code 2026-03-02} yields {@code 'FY25'}).
161	     * Returns {@code null} when no registration date is present.
162	     *
163	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
164	     * applied only where referenced via {@code qualifiedByName}.
165	     */
166	    @Named("formatFiscalYear")
167	    default String formatFiscalYear(Owner owner) {
168	        if (owner == null || owner.getRegistrationDate() == null) {
169	            return null;
170	        }
171	        return String.format("FY%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
172	    }
173	
174	    /**
175	     * Returns the calendar year in which the fiscal year containing {@code date} begins. The
176	     * fiscal year starts on 1 July, so dates in July through December belong to the fiscal year
177	     * starting in their own calendar year, while dates in January through June belong to the
178	     * fiscal year that started in the previous calendar year.
179	     */
180	    private static int fiscalYearStart(LocalDate date) {
181	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
182	    }
183	
184	    /**
185	     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
186	     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
187	     * code. Returns {@code null} when the customer code is absent.
188	     *
189	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
190	     * applied only where referenced via {@code qualifiedByName}.
191	     */
192	    @Named("formatCheckDigit")
193	    default Integer formatCheckDigit(Owner owner) {
194	        if (owner == null || owner.getCustomerCode() == null) {
195	            return null;
196	        }
197	        return LuhnCheckDigit.compute(owner.getCustomerCode());
198	    }
199	
200	    /**
201	     * Computes an owner's membership points, as required by the API's read-only
202	     * {@code membershipPoints} field: starting at 0, plus 2 when an email address is present,
203	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), plus 2 for a household
204	     * of 3 or more members, plus 3 when the owner's tenure spans at least one elapsed fiscal year
205	     * (the registration date's fiscal year precedes the current fiscal year, the fiscal year
206	     * starting on 1 July).
207	     *
208	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
209	     * applied only where referenced via {@code qualifiedByName}.
210	     */
211	    @Named("formatMembershipPoints")
212	    default Integer formatMembershipPoints(Owner owner) {
213	        if (owner == null) {
214	            return null;
215	        }
216	        int points = 0;
217	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
218	            points += 2;
219	        }
220	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
221	            points += 1;
222	        }
223	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
224	            points += 2;
225	        }
226	        if (owner.getRegistrationDate() != null
227	                && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1) {
228	            points += 3;
229	        }
230	        return points;
231	    }
232	
233	    /**
234	     * Derives an owner's membership level, as required by the API's read-only
235	     * {@code membershipLevel} field: a value from 1 to 4 mapped from the owner's
236	     * {@link #formatMembershipPoints membership points} — level 1 for 0-1 points, level 2 for
237	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
238	     *
239	     * <p>The result is then capped by the owner's {@link Owner#getMembershipLevelCap()
240	     * membershipLevelCap}, when present: a new owner's level cannot exceed one above the highest
241	     * membership level among the household members that already existed when it was created, so the
242	     * returned level is the lower of the derived level and that stored cap. When no cap applies (no
243	     * existing household member on creation) the derived level stands.
244	     *
245	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
246	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
247	     * to record the membership level on the create audit line).
248	     */
249	    @Named("formatMembershipLevel")
250	    default Integer formatMembershipLevel(Owner owner) {
251	        if (owner == null) {
252	            return null;
253	        }
254	        int points = formatMembershipPoints(owner);
255	        int level;
256	        if (points <= 1) {
257	            level = 1;
258	        }
259	        else if (points <= 3) {
260	            level = 2;
261	        }
262	        else if (points <= 5) {
263	            level = 3;
264	        }
265	        else {
266	            level = 4;
267	        }
268	        Integer cap = owner.getMembershipLevelCap();
269	        return (cap != null && cap < level) ? cap : level;
270	    }
271	
272	    /**
273	     * Derives an owner's locality, as required by the API's read-only {@code locality} field:
274	     * the {@code REGION} segment of the owner's {@code '<REGION>-<HASH8>'} customer code, so the
275	     * locality is read from the same region-and-hash identity that the customer code encodes.
276	     * When no customer code is present (e.g. an owner that predates the code), the region is
277	     * resolved directly from the postcode (falling back to the city-to-region table, else
278	     * {@code 'UNKNOWN'}), which yields the same region the code would have carried.
279	     *
280	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
281	     * applied only where referenced via {@code qualifiedByName}.
282	     */
283	    @Named("formatLocality")
284	    default String formatLocality(Owner owner) {
285	        if (owner == null) {
286	            return null;
287	        }
288	        String customerCode = owner.getCustomerCode();
289	        if (customerCode != null) {
290	            int dash = customerCode.indexOf('-');
291	            if (dash > 0) {
292	                return customerCode.substring(0, dash);
293	            }
294	        }
295	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
296	    }
297	
298	    /**
299	     * Derives an owner's timezone, as required by the API's read-only {@code timezone} field:
300	     * the IANA timezone name for the owner's {@link #formatLocality locality}/region, via the
301	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
302	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
303	     * {@code null} when the region has no mapped timezone (e.g. {@code 'UNKNOWN'}).
304	     *
305	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
306	     * applied only where referenced via {@code qualifiedByName}.
307	     */
308	    @Named("formatTimezone")
309	    default String formatTimezone(Owner owner) {
310	        if (owner == null) {
311	            return null;
312	        }
313	        return LocalityResolver.timezone(formatLocality(owner));
314	    }
315	
316	    /**
317	     * Derives an owner's preferred contact channel, as required by the API's read-only
318	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
319	     * otherwise {@code 'PHONE'}.
320	     *
321	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
322	     * applied only where referenced via {@code qualifiedByName}.
323	     */
324	    /**
325	     * Derives an owner's segment, as required by the API's read-only {@code ownerSegment} field:
326	     * {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'},
327	     * {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. {@code TIER} is {@code 'PREMIUM'}
328	     * when the owner's {@link #formatMembershipLevel membership level} is 3 or more, otherwise
329	     * {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the owner's {@link #formatLocality
330	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
331	     *
332	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
333	     * applied only where referenced via {@code qualifiedByName}.
334	     */
335	    @Named("formatOwnerSegment")
336	    default String formatOwnerSegment(Owner owner) {
337	        if (owner == null) {
338	            return null;
339	        }
340	        Integer level = formatMembershipLevel(owner);
341	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
342	        String area = LocalityResolver.timezone(formatLocality(owner)) != null ? "METRO" : "REGIONAL";
343	        return tier + "_" + area;
344	    }
345	
346	    @Named("formatContactPreference")
347	    default String formatContactPreference(Owner owner) {
348	        if (owner == null) {
349	            return null;
350	        }
351	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
352	    }
353	
354	    /**
355	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
356	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
357	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
358	     * no birth date was supplied (so the field is absent), or when no registration date is yet
359	     * known against which to compute the age.
360	     *
361	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
362	     * applied only where referenced via {@code qualifiedByName}.
363	     */
364	    @Named("formatAgeBand")
365	    default String formatAgeBand(Owner owner) {
366	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
367	            return null;
368	        }
369	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
370	        if (age < 18) {
371	            return "MINOR";
372	        }
373	        if (age < 65) {
374	            return "ADULT";
375	        }
376	        return "SENIOR";
377	    }
