388	    @Mapping(target = "id", ignore = true)
389	    @Mapping(target = "pets", ignore = true)
390	    @Mapping(target = "addressLine1", ignore = true)
391	    @Mapping(target = "addressLine2", ignore = true)
392	    @Mapping(target = "address", ignore = true)
393	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
394	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
395	    @Mapping(target = "title", source = "title", qualifiedByName = "mapTitle")
396	    Owner toOwner(OwnerFieldsDto ownerDto);
397	
398	    /**
399	     * Unwraps the owner-fields' optional honorific {@code title} enum into the stored
400	     * {@code String} form (its canonical value, e.g. {@code 'DR'}), or {@code null} when no
401	     * title was supplied. This is the single place the inbound title conversion lives: it runs
402	     * on the create path via {@link #toOwner(OwnerFieldsDto)} and is called directly on the
403	     * update path, keeping both consistent.
404	     *
405	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
406	     * applied only where referenced via {@code qualifiedByName}.
407	     */
408	    @Named("mapTitle")
409	    default String mapTitle(OwnerFieldsDto.TitleEnum title) {
410	        return title == null ? null : title.getValue();
411	    }
412	
413	    /**
414	     * Sets an owner's structured and composed address fields from the supplied owner-fields,
415	     * normalizing each. This is the single place the structured-field normalization rule lives: it
416	     * runs automatically after {@link #toOwner(OwnerFieldsDto)} via {@code @AfterMapping}, and is
417	     * called directly on the update path to keep both create and update consistent.
418	     *
419	     * <p>{@code addressLine1} and {@code addressLine2} are stored in their normalized forms and
420	     * {@code address} is set to the {@link #composeAddress composed} effective address.
421	     */
422	    @AfterMapping
423	    default void applyAddressFields(OwnerFieldsDto ownerDto, @MappingTarget Owner owner) {
424	        if (ownerDto == null) {
425	            return;
426	        }
427	        owner.setAddressLine1(normalizeAddress(ownerDto.getAddressLine1()));
428	        owner.setAddressLine2(normalizeAddress(ownerDto.getAddressLine2()));
429	        owner.setAddress(composeAddress(ownerDto));
430	    }
431	
432	    /**
433	     * Composes the effective, normalized postal address for an owner from the supplied fields,
434	     * preferring the structured form over the flat one. When a non-blank {@code addressLine1} is
435	     * present, the result is the normalized {@code addressLine1} with the normalized
436	     * {@code addressLine2} appended after a single space when an {@code addressLine2} is present;
437	     * otherwise it is the normalized flat {@code address}. Each part is normalized through
438	     * {@link #normalizeAddress} (trim, collapse whitespace, upper-case, expand {@code ST -> STREET},
439	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}).
440	     */
441	    default String composeAddress(OwnerFieldsDto ownerDto) {
442	        if (ownerDto == null) {
443	            return null;
444	        }
445	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
446	        if (line1 != null && !line1.isEmpty()) {
447	            String line2 = normalizeAddress(ownerDto.getAddressLine2());
448	            return (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
449	        }
450	        return normalizeAddress(ownerDto.getAddress());
451	    }
452	
453	    /**
454	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
455	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
456	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
457	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
458	     * {@code '12 MAIN STREET'}.
459	     *
460	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
461	     * only where referenced via {@code qualifiedByName}.
462	     */
463	    @Named("normalizeAddress")
464	    default String normalizeAddress(String address) {
465	        return AddressNormalizer.normalize(address);
466	    }
467	
468	    /**
469	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
470	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
471	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
472	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
473	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
474	     *
475	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
476	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
477	     *
478	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
479	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
480	     */
481	    @Named("normalizeTelephone")
482	    default String normalizeTelephone(String telephone) {
483	        return TelephoneNormalizer.toE164(telephone);
484	    }
485	
486	    /**
487	     * Normalizes an email address by lower-casing it, so it is stored and returned in a
488	     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
489	     * guarantees any value present is a syntactically valid address.
490	     *
491	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
492	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
493	     * e.g. on update).
494	     */
495	    @Named("normalizeEmail")
496	    default String normalizeEmail(String email) {
497	        return email == null ? null : email.toLowerCase(Locale.ROOT);
498	    }
499	
500	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
501	
502	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
503	
504	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
505	        OwnerPageDto ownerPageDto = new OwnerPageDto();
506	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
507	        ownerPageDto.setPage(ownerPage.getNumber());
508	        ownerPageDto.setSize(ownerPage.getSize());
509	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
510	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
511	        return ownerPageDto;
512	    }
513	}
