3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's 'locality' (canonical region) from the postcode and city.
7	 *
8	 * <p>The region is resolved by the postcode range first
9	 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), and only
10	 * falls back to the fixed city-to-region table ({@code Sydney -> NSW},
11	 * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}) when the postcode is absent or
12	 * in no known range. Preferring the postcode returns the same region for known cities
13	 * but disambiguates cities that share a name.
14	 *
15	 * <p>A city not covered by either lookup (or a {@code null} city with no matching
16	 * postcode) resolves to {@code 'UNKNOWN'}.
17	 */
18	public final class LocalityResolver {
19	
20	    /** City -> canonical region. Cities not listed derive locality 'UNKNOWN'. */
21	    private static final Map<String, String> CITY_REGION = Map.of(
22	        "Sydney", "NSW",
23	        "Melbourne", "VIC",
24	        "Brisbane", "QLD");
25	
26	    /**
27	     * Region -> inclusive 4-digit postcode range {low, high}. This is the single source of
28	     * truth for the region&harr;postcode relationship, read both here (postcode -> region)
29	     * and by {@link PostcodeValidator} (region -> range, via {@link #postcodeRange}).
30	     */
31	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
32	        "NSW", new int[] {2000, 2099},
33	        "VIC", new int[] {3000, 3099},
34	        "QLD", new int[] {4000, 4099});
35	
36	    /**
37	     * Region -> IANA timezone name. The fixed region-to-timezone table; regions not listed
38	     * (e.g. {@code 'UNKNOWN'}) have no mapped timezone.
39	     */
40	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
41	        "NSW", "Australia/Sydney",
42	        "VIC", "Australia/Melbourne",
43	        "QLD", "Australia/Brisbane");
44	
45	    /** Locality returned when neither the postcode nor the city resolves a region. */
46	    private static final String UNKNOWN = "UNKNOWN";
47	
48	    private LocalityResolver() {
49	    }
50	
51	    /**
52	     * Resolve the canonical region for a city, using the city-to-region table only.
53	     *
54	     * @param city the owner's city (any value)
55	     * @return the canonical region string, or {@code 'UNKNOWN'} when the city is not
56	     *         in the table.
57	     */
58	    public static String resolve(String city) {
59	        return CITY_REGION.getOrDefault(city, UNKNOWN);
60	    }
61	
62	    /**
63	     * Resolve the canonical region, preferring the postcode over the city. The region
64	     * is looked up by postcode range first; when the postcode is absent or in no known
65	     * range, the city-to-region table is used as a fallback.
66	     *
67	     * @param city     the owner's city (used as a fallback)
68	     * @param postcode the owner's postcode, or {@code null} when none was given
69	     * @return the canonical region string, or {@code 'UNKNOWN'} when neither lookup
70	     *         resolves a region.
71	     */
72	    public static String resolve(String city, String postcode) {
73	        String fromPostcode = resolveByPostcode(postcode);
74	        return fromPostcode != null ? fromPostcode : resolve(city);
75	    }
76	
77	    /**
78	     * The IANA timezone name for a region, via the fixed region-to-timezone table
79	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
80	     * {@code QLD -> Australia/Brisbane}).
